          "type": "p",
          "text": "If a health professional has given you personal heart, triglyceride, pregnancy, breastfeeding, medication, surgery, bleeding risk, allergy, kidney, liver, digestive, eating disorder, or medical nutrition guidance, follow that advice instead of using a general omega-3 label article as your decision rule."
