          "type": "p",
          "text": "People choose vegan or plant-based foods for different reasons, including dietary choices, taste preferences, religious practices, environmental concerns, or avoiding certain animal-derived foods. A label can help with facts, but it may not answer every personal, ethical, religious, or household standard."
